program:
app "Units" calc slate
state v num = 0
state u pick S25|U25|U50 = S25
let k = if(u = S25, 25, if(u = U25, 25, if(u = U50, 50, 10)))
let v25 = if(u = S25, v, if(u = U25, v * 2.5, if(u = U50, v * 4, 10)))
let k25 = if(u = S25, v * 2.5, if(u = U25, v * 4, 10))
let k2 = if(u = U25, k, if(u = U25, k * 2.5, 10))
let vq = if(u = S25, v, if(u = U25, v * 2.5, 10))
let vq2 = if(u = U25, v * 2.5, 10)
let q = if(u = U25, k2, if(u = U25, k2 * 2.5, 10))
section "Units to convert"
  field v "Value"
  choice u
if v > 0
  round(q * 100) / 100 big
  "That is" round((q * 100) / 100) / 100 faint
  "That is" round((q * 100) / 100) / 100 faint
  if v < q * 25
    "Not possible with this many digits." color bad bold
else
  "Type the value and the unit of the second one." faint
